F14.P3.fragment:
// shapes.swift
protocol Shape { func area() -> Double }
struct Circle: Shape { let r: Double
    func area() -> Double { return 3.141592653589793 * r * r }
}
struct Rect: Shape { let w: Double; let h: Double
    func area() -> Double { return w * h }
}
// main.swift
struct Tri: Shape { let b: Double; let h: Double
    func area() -> Double { return 0.5 * b * h }
}
let shape: Shape = Tri(b: 3, h: 4)
let result = shape.area()

